# ---------------------------------------------------------------------------
# GCURV_: Flow Register row D8-GH-CURVE-0003 (Curve Curvature), flowgeo_gen.py. The graph flowgeo_gcurv.dflow bakes one point per value under test (X = value,
# Y = case tag) and the section reads them back in baking order. Hand-computed oracle: t is the curve's own parameter (a circle's domain is 0..2 pi, so t = pi/2 is a quarter turn and a 0..1 fraction would not reach it). A circle of radius R has curvature 1/R everywhere, the vector pointing at the centre, and its osculating circle is the circle itself: R = 2.5 at the origin, t = pi/2, pi/4, pi: points (0,2.5,0), 2.5 (cos 45 degrees, sin 45 degrees, 0), (-2.5,0,0); vector length 0.4; centre = point + vector * R^2 = (0,0,0); the osculating circle has centre (0,0,0) (the area centroid), length 5 pi, area 6.25 pi, starts at the point with the curve's tangent; the arc of radius 4 (angles 0 to pi/2) at t = pi/4 has curvature 0.25 and the point (2 sqrt 2, 2 sqrt 2, 0); the circle of radius 2 about (1,2,3) in the plane with normal (1,1,1) has curvature 0.5, the centre (1,2,3) and its osculating circle lies on the circle; the parabola y = x^2 (the Bezier through (-1,1), (0,-1), (1,1), x = 2t - 1) has curvature 2 y''/(2 (1 + y'^2)^(3/2)): at t = 0.5 the point (0,0,0), the vector (0,2,0), the circle of radius 1/2 about (0,1/2,0); at t = 0.25 the point (-1/2,1/4,0), the vector (1/2,1/2,0), the circle of radius sqrt 2 about (1/2,5/4,0) (the evolute (x - y'(1 + y'^2)/y'', y + (1 + y'^2)/y'')); a straight line has curvature 0 and no circle.
# ---------------------------------------------------------------------------
sed "s|@GRAPH@|$HEREW/flowgeo_gcurv.dflow|g" "$HERE/flowgeo_gcurv_script.txt" > "$TMPW/flowgeo_gcurv_script.txt"
if [ -n "${DISPLAY:-}" ] && xset q >/dev/null 2>&1 || ! command -v xvfb-run >/dev/null 2>&1; then
  FR_OUT="$(timeout 900 "$BIN" --smoke 30 --script "$TMPW/flowgeo_gcurv_script.txt" 2>&1)" || { echo "$FR_OUT" | tail -20; echo "FAIL GCURV_run: script exited non-zero"; fail=1; FR_OUT=""; }
else
  FR_OUT="$(timeout 900 xvfb-run -a -s "-screen 0 1600x900x24" "$BIN" --smoke 30 --script "$TMPW/flowgeo_gcurv_script.txt" 2>&1)" || { echo "$FR_OUT" | tail -20; echo "FAIL GCURV_run: script exited non-zero"; fail=1; FR_OUT=""; }
fi
# fr_chk TAG "x1 x2 ..." MESSAGE: the points baked with Y = TAG have exactly these X values, in this order
fr_chk() {
  local got
  got="$({ grep -oE "  [-0-9.e+]+,$1,0\$" <<<"$FR_OUT" || true; } | sed -E 's/^ +//; s/,[^,]*,0$//' | tr '\n' ' ' | sed -E 's/ $//')"
  if [ "$got" = "$2" ]; then echo "ok   GCURV_$1: $3 (measured '$got')"; else echo "FAIL GCURV_$1: $3 (measured '$got', expected '$2')"; fail=1; fi
}
if grep -qF "GrasshopperPlayer: solved 410 node(s)" <<<"$FR_OUT"; then echo "ok   GCURV_solve: the player solved all 410 nodes (every node type is registered)"; else echo "FAIL GCURV_solve: expected 'solved 410 node(s)'"; fail=1; fi
if grep -qE "^ok +expect_objects 74 " <<<"$FR_OUT"; then echo "ok   GCURV_objects: exactly 74 point(s) baked"; else echo "FAIL GCURV_objects: expected 74 baked objects"; fail=1; fi
